fun analyzeAnomalyData(target: String, openPorts: List<String>, timestamp: String): Map<String, Boolean> {
    val anomalyMap = mutableMapOf("target" to target)

    if (openPorts.isNotEmpty()) {
        // Filter out the scan method that is not "native-net"
        val nativeNetOpenPorts = openPorts.filter { it.startsWith("13") }

        // Create a map for anomaly detection based on the scan method
        val anomalyMap = Map.ofWith { _, result ->
            if (result) {
                // Check each port and timestamp to see if there are any anomalies
                if (timestamp.contains(result[0].toString())) {
                    return@map
                }

                if (target.equals(result[0])) {
                    return@map true
                }

                // Log the result in a human-readable format
                anomalyMap[result[0]] = "Anomaly detected: Port ${result[0]}, Timestamp ${timestamp}"
            }
        }
